import"./chunk-2NFLSA4Y.js";var s={spring:{theory:{concept:"[[Hooke's law: when a spring is stretched or compressed slightly, the elastic force is proportional to the deformation and points the opposite way, F = \u2212k\xB7x.]]"},section:{hooke:{title:"Hooke's law",text:"[[In 1676 Robert Hooke found that the force of a spring is proportional to how far it is stretched or squeezed: F = \u2212k\xB7x.]] The stiffness k tells how many newtons are needed per metre: a soft spring might have 5 N/m, a car's suspension spring tens of thousands. The minus sign means the force always points back towards the resting position. The law holds as long as the spring is not stretched too far."},oscillation:{title:"Why it swings",text:"Pull the mass down and let go: the spring pulls it up, it speeds up, and at the middle it is moving fastest, so it overshoots. Now the spring pushes it back down, and so on. The middle is where the spring's pull exactly balances the weight \u2014 the equilibrium position. The mass swings around it, like a pendulum swings around its lowest point."},period:{title:"The rhythm: T = 2\u03C0\xB7\u221A(m/k)",text:"[[The time for one full swing, the period, depends only on the mass and the stiffness: a heavier mass swings more slowly, a stiffer spring faster.]] Four times the mass doubles the period. Remarkably, the period does not depend on how far you pull: a big swing travels further but also faster, and takes the same time. That is why springs keep time in mechanical watches."},energy:{title:"Energy goes back and forth",text:"A stretched spring stores elastic energy \xBD\xB7k\xB7x\xB2; a moving mass carries kinetic energy \xBD\xB7m\xB7v\xB2. At the ends of the swing all the energy is in the spring; in the middle all of it is in the motion. Without damping the total stays exactly the same, and the swing would go on forever."},damping:{title:"Damping",text:"In reality air and friction slowly take energy away, and the swings get smaller: damping. With a damping force \u2212b\xB7v the amplitude halves every 2\xB7m\xB7ln 2 / b seconds. With strong damping the mass does not swing at all; with exactly the right amount \u2014 critical damping, \u03B6 = 1 \u2014 it returns to the middle as fast as possible without overshooting. Car shock absorbers are designed to be close to that."},everyday:{title:"Springs and oscillations around us",text:"Car suspensions, trampolines, bungee ropes, spring scales and mattresses all follow Hooke's law. The balance spring of a mechanical watch swings a few times every second. Even the atoms of a solid behave like masses joined by tiny springs \u2014 that is how sound and heat travel through it."},check:{title:"Check your understanding",text:"A spring with k = 20 N/m is stretched by 0.3 m. What force does it pull with? (6 N.) The mass is made four times bigger. What happens to the period? (It doubles.) The mass is pulled twice as far. What happens to the period? (Nothing.) Where is the mass fastest? (In the middle, at the equilibrium position.) Test each answer in the simulation."}},formula:{hooke:"Hooke's law: the force of a spring",period:"Period of a mass on a spring (no damping)",frequency:"Frequency: swings per second",energy:"Elastic plus kinetic energy",motion:"Equation of motion with damping",dampingRatio:"Damping ratio: \u03B6 = 1 is critical damping"},variable:{force:"Force of the spring",constant:"Stiffness of the spring",displacement:"Distance from the equilibrium position",period:"Period",damping:"Damping coefficient"},assumption:{equilibrium:"The displacement is measured from the equilibrium position, where the spring's static stretch m\xB7g/k already balances the weight.",linear:"The spring has no mass and obeys Hooke's law over the whole range shown; the mass moves only up and down.",damping:"Damping is a force proportional to the speed, \u2212b\xB7v."},param:{mass:"Mass",springConstant:"Stiffness of the spring k",amplitude:"Pulled down at the start",damping:"Damping b",timeStep:"Time step"},hint:{mass:"A heavier mass swings more slowly.",springConstant:"Newtons needed per metre of stretch. A stiffer spring swings faster.",amplitude:"How far the mass is pulled below the equilibrium position before it is let go.",damping:"Takes energy away, so the swings get smaller. 0 means no damping."},preset:{soft:"Soft",medium:"Medium",stiff:"Stiff"},measure:{displacement:"Distance from equilibrium",springForce:"Force of the spring",period:"Period",frequency:"Frequency",staticStretch:"Stretch caused by the weight",dampingRatio:"Damping ratio",elasticEnergy:"Elastic energy"},graph:{displacement:"Distance from equilibrium against time",energy:"Energy against time"},challenge:{oneSecond:{title:"One swing per second",description:"Make the mass swing with a period of exactly 1 s.",hint:"T = 2\u03C0\xB7\u221A(m/k): with 1 kg you need about 39.5 N/m."},slowSwing:{title:"A slow swing on a strong spring",description:"With a spring of at least 20 N/m, make the period exactly 2 s.",hint:"m = k \xB7 (T / 2\u03C0)\xB2: with 20 N/m you need about 2 kg."},strongPull:{title:"A strong pull",description:"Pull the mass down by no more than 0.3 m and make the spring pull back with at least 20 N.",hint:"F = k\xB7x: you need a stiff spring."},quickFade:{title:"Fading fast",description:"Make the swings halve within 2 s \u2014 but still swing.",hint:"The amplitude halves in 2\xB7m\xB7ln 2 / b seconds, so b \u2265 0.7 \xB7 m."},critical:{title:"Critical damping",description:"Find the damping at which the mass returns to the middle as fast as possible without overshooting (\u03B6 = 1).",hint:"b = 2\xB7\u221A(k\xB7m): with 20 N/m and 1 kg that is about 8.9 kg/s."}}}},i={sim:s};export{i as default,s as sim};
